import Foundation
import SafeDICore
import Testing
@testable import SafeDIToolLibrary
@testable import SafeDIToolTestSupport

struct SafeDIToolMockOnlyTests: ~Copyable {
	// MARK: Initialization

	init() throws {
		filesToDelete = [URL]()
	}

	deinit {
		for fileToDelete in filesToDelete {
			try! FileManager.default.removeItem(at: fileToDelete)
		}
	}

	// MARK: Tests

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_usesDefaultFromMockOnlyExtension_whenForwardedPropertyHasMockOnlyDeclaration() async throws {
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(isRoot: true, generateMock: true)
				public struct Root: Instantiable {
				    public init(featureBuilder: Instantiator<Feature>) {
				        self.featureBuilder = featureBuilder
				    }
				    @Instantiated let featureBuilder: Instantiator<Feature>
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Feature: Instantiable {
				    public init(name: String) {
				        self.name = name
				    }
				    @Forwarded let name: String
				}
				""",
				"""
				@Instantiable(mockOnly: true)
				extension String: Instantiable {
				    public static func mock() -> String { "" }
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles["Feature+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Feature {
		    static func mock(
		        name: String = String.mock()
		    ) -> Feature {
		        return Feature(name: name)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Feature+SafeDIMock.swift"] ?? "")")
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_usesDefaultFromMockOnlyExtension_whenExtensionIsGuardedByMockConditionalCompilation() async throws {
		// No compilation condition is supplied: the extension only feeds mock
		// generation, and the generated mock is itself wrapped in `#if DEBUG`.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(isRoot: true, generateMock: true)
				public struct Root: Instantiable {
				    public init(featureBuilder: Instantiator<Feature>) {
				        self.featureBuilder = featureBuilder
				    }
				    @Instantiated let featureBuilder: Instantiator<Feature>
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Feature: Instantiable {
				    public init(name: String) {
				        self.name = name
				    }
				    @Forwarded let name: String
				}
				""",
				"""
				#if DEBUG
				@Instantiable(mockOnly: true)
				extension String: Instantiable {
				    public static func mock() -> String { "" }
				}
				#endif
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles["Feature+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Feature {
		    static func mock(
		        name: String = String.mock()
		    ) -> Feature {
		        return Feature(name: name)
		    }
		}
		#endif
		""", "Unexpected output \(output.mockFiles["Feature+SafeDIMock.swift"] ?? "")")
	}

