	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_skipsMockOnlyExtension_whenGuardedByMockConditionAndMocksAreUnconditional() async throws {
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				#SafeDIConfiguration(mockConditionalCompilation: nil)
				""",
				"""
				@Instantiable(isRoot: true, generateMock: true)
				public struct Root: Instantiable {
				    public init(featureBuilder: Instantiator<Feature>) {
				        self.featureBuilder = featureBuilder
				    }
				    @Instantiated let featureBuilder: Instantiator<Feature>
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Feature: Instantiable {
				    public init(name: String) {
				        self.name = name
				    }
				    @Forwarded let name: String
				}
				""",
				"""
				#if DEBUG
				@Instantiable(mockOnly: true)
				extension String: Instantiable {
				    public static func mock() -> String { "" }
				}
				#endif
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
			// The verification compile defines `DEBUG`, so the assertion below fails it on purpose.
			skipCompileVerification: true,
		)

		#expect(output.mockFiles["Feature+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		#error("SafeDI scanned this module assuming `#if DEBUG` was inactive, but it is active in this compilation. Report the conditions this target compiles with to SafeDITool, as the \\"Reporting active conditions\\" section of the SafeDI manual describes for your build system.")
		#endif

		extension Feature {
		    static func mock(
		        name: String
		    ) -> Feature {
		        return Feature(name: name)
		    }
		}
		""", "Unexpected output \(output.mockFiles["Feature+SafeDIMock.swift"] ?? "")")
	}

	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_usesDefaultFromMockOnlyExtension_whenExtensionIsGuardedByNegatedDebugAndMocksAreUnconditional() async throws {
		// The configuration is in `File.swift`, so the module is walked a second time once it is found.
		// The `…AndConfigurationIsInSafeDIConfigurationFile` variant covers reading it first.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				#SafeDIConfiguration(mockConditionalCompilation: nil)
				""",
				"""
				@Instantiable(isRoot: true, generateMock: true)
				public struct Root: Instantiable {
				    public init(featureBuilder: Instantiator<Feature>) {
				        self.featureBuilder = featureBuilder
				    }
				    @Instantiated let featureBuilder: Instantiator<Feature>
				}
				""",
				"""
				@Instantiable(generateMock: true)
				public struct Feature: Instantiable {
				    public init(name: String) {
				        self.name = name
				    }
				    @Forwarded let name: String
				}
				""",
				"""
				#if !DEBUG
				@Instantiable(mockOnly: true)
				extension String: Instantiable {
				    public static func mock() -> String { "" }
				}
				#endif
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
			// The verification compile defines `DEBUG`, so the assertion below fails it on purpose.
			skipCompileVerification: true,
		)

		#expect(output.mockFiles["Feature+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if !(!DEBUG)
		#error("SafeDI scanned this module assuming `#if !DEBUG` was active, but it is inactive in this compilation. Report the conditions this target compiles with to SafeDITool, as the \\"Reporting active conditions\\" section of the SafeDI manual describes for your build system.")
		#endif

		extension Feature {
		    static func mock(
		        name: String = String.mock()
		    ) -> Feature {
		        return Feature(name: name)
		    }
		}
		""", "Unexpected output \(output.mockFiles["Feature+SafeDIMock.swift"] ?? "")")
	}

