	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_usesDefaultFromMockOnlyExtension_whenInstantiatedPropertyHasMockOnlyDeclaration() async throws {
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable
				public struct ExternalService: Instantiable {
				    public init() {}
				}
				""",
				"""
				@Instantiable(isRoot: true, generateMock: true)
				public struct Root: Instantiable {
				    public init(service: ExternalService) {
				        self.service = service
				    }
				    @Instantiated let service: ExternalService
				}
				""",
				"""
				@Instantiable(mockOnly: true)
				extension ExternalService {
				    public static func mock() -> ExternalService { fatalError() }
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		#expect(output.mockFiles.count == 1)
		#expect(output.mockFiles["Root+SafeDIMock.swift"] == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Root {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            service: (() -> ExternalService)? = nil
		        ) {
		            __safeDI_storage = __safeDI_Storage(
		                service: service
		            )
		        }

		        var service: (() -> ExternalService)? { __safeDI_storage.service }

		        private let __safeDI_storage: __safeDI_Storage

		        private final class __safeDI_Storage {
		            init(
		                service: (() -> ExternalService)?
		            ) {
		                self.service = service
