	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_doesNotUseMockOnlyScope_whenMockReturnTypeIncompatibleWithNewSlot() async throws {
		// Production MyService claims only ServiceProtocol (not OtherProtocol).
		// mockOnly claims both ServiceProtocol and OtherProtocol, but
		// mock() -> ServiceProtocol. The OtherProtocol slot has no production
		// entry — only the mockOnly provides it — so the scope map's new-slot
		// path is used. The mockOnly scope should NOT be installed for
		// OtherProtocol because the mock is incompatible. Root references
		// OtherProtocol via fulfilledByType, which resolves in production.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				public protocol ServiceProtocol {}
				public protocol OtherProtocol {}
				""",
				"""
				@Instantiable(isRoot: true, generateMock: true)
				public struct Root: Instantiable {
				    public init(other: OtherProtocol) {
				        self.other = other
				    }
				    @Instantiated(fulfilledByType: "MyService") let other: OtherProtocol
				}
				""",
				"""
				@Instantiable
				public struct MyService: Instantiable, ServiceProtocol, OtherProtocol {
				    public init() {}
				}

				@Instantiable(fulfillingAdditionalTypes: [ServiceProtocol.self, OtherProtocol.self], mockOnly: true)
				extension MyService {
				    public static func mock() -> ServiceProtocol { MyService() }
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)

		let rootMock = output.mockFiles["Root+SafeDIMock.swift"] ?? ""
		// OtherProtocol should use MyService.init (production scope, no mock),
		// NOT MyService.mock (which returns ServiceProtocol, incompatible).
		#expect(rootMock == """
		// This file was generated by the SafeDIGenerateDependencyTree build tool plugin.
		// Any modifications made to this file will be overwritten on subsequent builds.
		// Please refrain from editing this file directly.

		#if DEBUG
		extension Root {
		    /// Overrides for the mock dependency tree.
		    struct SafeDIOverrides {
		        init(
		            other: (() -> OtherProtocol)? = nil
		        ) {
		            __safeDI_storage = __safeDI_Storage(
		                other: other
		            )
		        }

		        var other: (() -> OtherProtocol)? { __safeDI_storage.other }

		        private let __safeDI_storage: __safeDI_Storage

		        private final class __safeDI_Storage {
		            init(
		                other: (() -> OtherProtocol)?
		            ) {
		                self.other = other
		            }

		            let other: (() -> OtherProtocol)?
		        }
		    }

		    static func mock(
		        safeDIOverrides: SafeDIOverrides = .init()
		    ) -> Root {
		        let other: OtherProtocol = if let safeDIBuilder = safeDIOverrides.other { safeDIBuilder() } else { MyService() }
		        return Root(other: other)
		    }
		}
		#endif
		""", "Unexpected output \(rootMock)")
	}

