	mutating func mock_buildsTypeByInitializerAndByHandWrittenMockBeneathCycleEdge_whenRootWithCycleEdgeSortsFirst() async throws {
		// `Root` builds `MyService` with its hand-written mock only beneath the cycle edge `Second` -> `First`, where
		// nothing reads its configuration, and `Zulu` builds it with `init`. The configuration describes `init`.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
