				}
				""",
				"""
				public protocol ServiceProtocol {}
				""",
				"""
				@Instantiable
				public struct Database: Instantiable {
				    public init() {}
				}
				""",
				"""
				@Instantiable
				public struct Logger: Instantiable {
				    public init() {}
				}
				""",
				"""
