	@Test
	@available(macOS 13.0, iOS 16.0, tvOS 16.0, watchOS 9.0, *)
	mutating func mock_generatesConfigurationsNestedInConfigurationOfTypeBuiltOnlyBeneathRepeatedAncestor_whenNestedTypesReadNothing() async throws {
		// Issue #720's shape where `Gamma`, whose construction reads its hand-written mock's default, builds `Delta`, which
		// builds `Epsilon`, which builds `Zeta`, all only beneath the inner `Alpha`. `Delta` and `Epsilon` read nothing, but
		// `Gamma`'s configuration nests `Delta`'s, which nests `Epsilon`'s, so both are generated.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(generateMock: true)
				public struct Root: Instantiable {
				    public init(alpha: AlphaProtocol) { self.alpha = alpha }
				    @Instantiated let alpha: AlphaProtocol
				}
				""",
				"""
				public protocol AlphaProtocol {}

				@Instantiable(fulfillingAdditionalTypes: [AlphaProtocol.self])
				public struct Alpha: AlphaProtocol, Instantiable {
				    public init(beta: Instantiator<Beta>, gamma: Gamma) {
				        self.beta = beta
				        self.gamma = gamma
				    }
				    @Instantiated let beta: Instantiator<Beta>
				    @Instantiated let gamma: Gamma
				}

				@Instantiable(fulfillingAdditionalTypes: [AlphaProtocol.self], mockOnly: true)
				extension Alpha {
				    public static func mock(beta: Instantiator<Beta> = Instantiator { .unused() }) -> AlphaProtocol {
				        Alpha(beta: beta, gamma: Gamma(delta: Delta(epsilon: Epsilon(zeta: Zeta()))))
				    }
				}
				""",
				"""
				extension Beta {
				    public static func unused() -> Beta {
				        Beta(alphaBuilder: Instantiator { Alpha(beta: Instantiator { unused() }, gamma: Gamma(delta: Delta(epsilon: Epsilon(zeta: Zeta())))) })
				    }
				}

				@Instantiable
				public struct Beta: Instantiable {
				    public init(alphaBuilder: Instantiator<Alpha>) { self.alphaBuilder = alphaBuilder }
				    @Instantiated let alphaBuilder: Instantiator<Alpha>
				}
				""",
				"""
				@Instantiable
				public struct Delta: Instantiable {
				    public init(epsilon: Epsilon) {
				        self.epsilon = epsilon
				    }
				    @Instantiated let epsilon: Epsilon
				}
				""",
				"""
				@Instantiable
				public struct Epsilon: Instantiable {
				    public init(zeta: Zeta) {
				        self.zeta = zeta
				    }
				    @Instantiated let zeta: Zeta
				}
				""",
				"""
				public protocol GammaProtocol {}

				@Instantiable(fulfillingAdditionalTypes: [GammaProtocol.self])
				public struct Gamma: GammaProtocol, Instantiable {
				    public init(flag: Bool = true, delta: Delta) {
				        self.delta = delta
				    }
				    @Instantiated let delta: Delta
				}

