		            func __safeDI_beta() -> Beta {
		                func __safeDI_alphaBuilder() -> Alpha {
		                    let beta = Instantiator<Beta>(__safeDI_beta)
		                    func __safeDI_gamma() -> Gamma {
		                        func __safeDI_delta() -> Delta {
		                            func __safeDI_epsilon() -> Epsilon {
