	/// Two roots, each building `Gamma` only beneath a repeated ancestor: `rootBuildingWithInitializer` through `Kappa`,
	/// whose property of type `Gamma` is built with `Gamma`'s initializer, and `rootBuildingWithHandWrittenMock` through
	/// `Omega`, whose property of type `GammaProtocol` is built with `Gamma`'s hand-written mock, which takes `label` and
	/// not `delta`. `Kappa` and `Omega` each read their hand-written mock's `count` from their configuration, which nests
	/// `Gamma`'s.
	@Test
	mutating func mock_appendsConfigurationToMockedTypesOwnMock_whenMockedTypeIsConfiguredOnlyBeneathRepeatedAncestorOfAnotherRoot() async throws {
		// `Gamma` generates a mock of its own and is built in `Root`’s tree only beneath the repeated `Alpha`, which
		// `Root` builds with its hand-written mock first. `Gamma`’s configuration, which that build reads, is declared in
		// `Gamma`’s own mock file, as a mocked type’s configuration always is.
		let output = try await executeSafeDIToolTest(
			swiftFileContent: [
				"""
				@Instantiable(generateMock: true)
				public struct Root: Instantiable {
				    public init(alpha: AlphaProtocol) { self.alpha = alpha }
				    @Instantiated let alpha: AlphaProtocol
				}
				""",
				"""
				public protocol AlphaProtocol {}

				@Instantiable(fulfillingAdditionalTypes: [AlphaProtocol.self])
				public struct Alpha: AlphaProtocol, Instantiable {
				    public init(beta: Instantiator<Beta>, gamma: Gamma) {
				        self.beta = beta
				        self.gamma = gamma
				    }
				    @Instantiated let beta: Instantiator<Beta>
				    @Instantiated let gamma: Gamma
				}

				@Instantiable(fulfillingAdditionalTypes: [AlphaProtocol.self], mockOnly: true)
				extension Alpha {
				    public static func mock(beta: Instantiator<Beta> = Instantiator { .unused() }) -> AlphaProtocol {
				        Alpha(beta: beta, gamma: Gamma())
				    }
				}
				""",
				"""
				extension Beta {
				    public static func unused() -> Beta {
				        Beta(alphaBuilder: Instantiator { Alpha(beta: Instantiator { unused() }, gamma: Gamma()) })
				    }
				}

				@Instantiable
				public struct Beta: Instantiable {
				    public init(alphaBuilder: Instantiator<Alpha>) { self.alphaBuilder = alphaBuilder }
				    @Instantiated let alphaBuilder: Instantiator<Alpha>
				}
				""",
				"""
				public protocol GammaProtocol {}

				@Instantiable(fulfillingAdditionalTypes: [GammaProtocol.self], generateMock: true)
				public struct Gamma: GammaProtocol, Instantiable {
				    public init(flag: Bool = true) {}
				}

				@Instantiable(fulfillingAdditionalTypes: [GammaProtocol.self], mockOnly: true, customMockName: "preview")
				extension Gamma {
				    public static func preview(flag: Bool = true) -> GammaProtocol { Gamma(flag: flag) }
				}
				""",
			],
			buildSwiftOutputDirectory: true,
			filesToDelete: &filesToDelete,
		)
		#expect(output.mockFiles["Gamma+SafeDIMock.swift"] == """
