		    /// Overrides how `Gamma` is constructed. Parameters match the type’s initializer or custom mock method.
		    public var safeDIBuilder: ((Bool) -> Gamma)? { __safeDI_storage.safeDIBuilder }

		    private let __safeDI_storage: __safeDI_Storage

		    private final class __safeDI_Storage {
		        init(
		            flag: Bool?,
		            safeDIBuilder: ((Bool) -> Gamma)?
		        ) {
		            self.flag = flag
		            self.safeDIBuilder = safeDIBuilder
		        }

		        let flag: Bool?
		        let safeDIBuilder: ((Bool) -> Gamma)?
		    }
		}

		extension Gamma {
		    static func __safeDI_init(flag: Bool?, safeDIBuilder: ((Bool) -> Gamma)?) -> Gamma {
		        let flag = flag ?? (true)
		        return if let safeDIBuilder { safeDIBuilder(flag) } else { Gamma(flag: flag) }
		    }
		}
		#endif

		""")
	}

	private static func typeConfiguredBeneathRepeatedAncestorsTwoWays(rootBuildingWithInitializer: String, rootBuildingWithHandWrittenMock: String) -> [String] {
